const body = $input.first().json.body || {};
const taskId = String(body.task_id || '').trim();
const planId = String(body.plan_id || '').trim();
const sourceBrief = String(body.source_brief || '').trim();
const referenceTitle = String(body.reference_title || '').trim();
const productType = ['single', 'one', 'two'].includes(body.product_type) ? body.product_type : 'one';
const products = Array.isArray(body.products) ? body.products.map(item => ({
  sub_task_id: String(item?.sub_task_id || '').trim(),
  set_index: Number(item?.set_index) || 0,
})) : [];
const variants = productType === 'single' ? [] : (Array.isArray(body.variants) ? body.variants.map(item => ({
  id: String(item?.id || '').trim(),
  option1: String(item?.option1 || '').trim(),
  option2: String(item?.option2 || '').trim(),
  tier1_name: String(item?.tier1_name || '').trim(),
  tier2_name: String(item?.tier2_name || '').trim(),
  sku_description: String(item?.sku_description || '').trim(),
})) : []);
const callbackSecret = String(body.callback_secret || '');
const callbackUrl = String(body.callback_url || '').trim();

if (!taskId || !planId || !callbackUrl || body.workflow_type !== 'metadata') throw new Error('缺少task_id、plan_id、callback_url或workflow_type');
if (sourceBrief.length < 10 || sourceBrief.length > 2000) throw new Error('source_brief必须为10~2000字符');
if (!products.length || products.length > 10 || products.some(item => !item.sub_task_id)) throw new Error('products必须包含1~10条有效记录');
if (new Set(products.map(item => item.sub_task_id)).size !== products.length) throw new Error('products中的sub_task_id重复');
if (variants.length > 100 || variants.some(item => !item.id || !item.option1)) throw new Error('variants包含无效记录');
if (new Set(variants.map(item => item.id)).size !== variants.length) throw new Error('variants中的id重复');
if (products.length * variants.length > 100) throw new Error('单批SKU标题数量不能超过100');

const outputShape = {
  products: products.map(product => ({
    sub_task_id: product.sub_task_id,
    product_title: '商品标题',
    recommended_copy: '推荐文案',
    product_description: '商品描述',
    sku_titles: variants.map(variant => ({ variant_id: variant.id, title: 'SKU标题' })),
  })),
};
const finalPrompt = `你是国内电商商品信息编辑。根据确定的商品事实，一次生成聚水潭模板需要的商品标题、推荐文案、商品描述和SKU标题。

商品事实：
${sourceBrief}

可选参考标题：
${referenceTitle || '无'}

本批商品：
${JSON.stringify(products, null, 2)}

规格组合：
${JSON.stringify(variants, null, 2)}

严格输出结构：
${JSON.stringify(outputShape, null, 2)}

要求：
1. 只输出一个严格JSON对象，不要Markdown、代码围栏、注释或解释。
2. products必须严格保留输入的sub_task_id和数量，不得增删、改写或重复。
3. 每套商品生成有差异但事实一致的product_title，长度1~200字符，符合国内电商搜索习惯，不堆砌无关词。
4. recommended_copy长度1~1000字符，product_description长度1~3000字符，只使用商品事实中明确的信息。
5. 禁止虚构品牌、材质、认证、产地、赠品、保修、疗效、销量、价格或夸大承诺。
6. 每套sku_titles必须严格保留全部variant_id及数量；title长度1~30字符，清楚包含对应完整规格值，可追加简短事实卖点。
7. 同一一级规格在二维组合中含义必须一致，不得合并、拆分或改写规格组合。
8. variants为空时，每套sku_titles必须返回空数组。`;

return { taskId, planId, products, variants, finalPrompt, callbackSecret, callbackUrl };

const response = $input.first().json;
const original = $node['提取参数'].json;
let content = response?.choices?.[0]?.message?.content;
if (typeof content !== 'string') throw new Error('模型未返回商品元数据');
content = content.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
let parsed;
try { parsed = JSON.parse(content); } catch (_) { throw new Error('商品元数据不是合法JSON对象'); }
if (!parsed || Array.isArray(parsed) || !Array.isArray(parsed.products)) throw new Error('商品元数据必须包含products数组');
if (parsed.products.length !== original.products.length) throw new Error(`products数量不匹配: ${parsed.products.length}/${original.products.length}`);
const productMap = new Map(parsed.products.map(item => [String(item?.sub_task_id || ''), item]));
if (productMap.has('') || productMap.size !== parsed.products.length) throw new Error('products中的sub_task_id缺失或重复');
const variantIds = new Set(original.variants.map(item => item.id));
const normalize = (value, min, max, label) => {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  if (text.length < min || text.length > max) throw new Error(`${label}长度必须为${min}~${max}字符`);
  return text;
};
const products = original.products.map((source, productIndex) => {
  const item = productMap.get(source.sub_task_id);
  if (!item) throw new Error(`缺少sub_task_id: ${source.sub_task_id}`);
  if (!Array.isArray(item.sku_titles) || item.sku_titles.length !== original.variants.length) throw new Error(`第${productIndex + 1}套sku_titles数量不匹配`);
  const skuMap = new Map(item.sku_titles.map(sku => [String(sku?.variant_id || ''), sku]));
  if (skuMap.has('') || skuMap.size !== item.sku_titles.length) throw new Error(`第${productIndex + 1}套variant_id缺失或重复`);
  const skuTitles = original.variants.map((variant, variantIndex) => {
    const sku = skuMap.get(variant.id);
    if (!sku || !variantIds.has(variant.id)) throw new Error(`第${productIndex + 1}套缺少变体${variant.id}`);
    return { variant_id: variant.id, title: normalize(sku.title, 1, 30, `SKU标题#${productIndex + 1}-${variantIndex + 1}`) };
  });
  return {
    sub_task_id: source.sub_task_id,
    product_title: normalize(item.product_title, 1, 200, `商品标题#${productIndex + 1}`),
    recommended_copy: normalize(item.recommended_copy, 1, 1000, `推荐文案#${productIndex + 1}`),
    product_description: normalize(item.product_description, 1, 3000, `商品描述#${productIndex + 1}`),
    sku_titles: skuTitles,
  };
});
return { callback_secret: original.callbackSecret, task_id: original.taskId, plan_id: original.planId, workflow_type: 'metadata', products, callbackUrl: original.callbackUrl };

const body = $node['Webhook'].json.body || {};
const input = $input.first().json || {};
const message = String(input.error?.message || input.message || input.error || '商品元数据工作流执行失败').slice(0, 500);
return { callback_secret: String(body.callback_secret || ''), task_id: String(body.task_id || ''), plan_id: String(body.plan_id || ''), workflow_type: 'metadata', error: message, retryable: true, callbackUrl: String(body.callback_url || '') };
